import os, re, json

d = os.environ['RLM_SESSION_DIR']
session_file = f'{d}/../../sessions/{os.path.basename(d)}.jsonl'

print(f"Loading session file: {session_file}")
with open(session_file, 'r') as f:
    content = f.read()

# Parse all user messages and get their text content
messages = []
for line in content.split('\n'):
    if line:
        try:
            msg = json.loads(line)
            # Extract text from user messages
            if (msg.get('role') in ['user', 'assistant', 'tool', 'error', 'sender']) or 'role' in str(msg):
                text = msg.get('content', [])
                if isinstance(text, list):
                    for item in text:
                        if isinstance(item, dict) and 'text' in item:
                            messages.append(item['text'])
        except:
            msg_content = msg.get('content', '')
            if isinstance(msg_content, list):
                for item in msg_content:
                    if isinstance(item, dict) and 'text' in item:
                        messages.append(item['text'])
            elif isinstance(msg_content, str):
                messages.append(msg_content)

print(f"Found {len(messages)} messages")

# Now search each message for demo pairs
for i, msg in enumerate(messages):
    # Look for Demo pair pattern
    if 'Demo pair' in msg:
        # Check for actual demo data (grid rows of numbers)
        # The text would have "Demo pair N (HxW):" followed by grid rows
        pattern = r'Demo pair \s*\d+\s*\(\d+x\d+\):\n([\s\S]+?)(?=Demo pair|\n\nNew instance|Test input|$)'
        matches = re.findall(pattern, msg)
        for j, match in enumerate(matches):
            print(f"\n=== Demo pair found in message {i} ===")
            lines = [l.strip() for l in match.strip().split('\n')]
            for l in lines[:10]:
                print(f"  {l}")

# If no Demo pairs found, let's look at the whole message text structure
print(f"\n=== All messages (looking for Demo pairs) ===")
for i, msg in enumerate(messages[:5]):  # First 5 messages
    print(f"\n--- Message {i} (first 2000 chars) ---")
    print(msg[:2000])

